},{"name":"Final status and benefits report","description":"Outcome versus plan for the client.","priority":"High","tasks":[{"title":"Compile final status","priority":"Low","day1_critical":"N","effort_hours":34},{"title":"Calculate benefits delivered","priority":"Medium","day1_critical":"N","effort_hours":23},{"title":"Partner review","priority":"Medium","day1_critical":"N","effort_hours":4},{"title":"Issue report to client","priority":"High","day1_critical":"N","effort_hours":6}]},{"name":"Archive and access removal","description":"Retention, archive and removal of access.","priority":"Medium","tasks":[{"title":"Archive engagement files","priority":"Medium","day1_critical":"N","effort_hours":30},{"title":"Apply retention schedule","priority":"Low","day1_critical":"N","effort_hours":7},{"title":"Remove team access","priority":"High","day1_critical":"N","effort_hours":10},{"title":"DPO confirmation","priority":"High","day1_critical":"N","effort_hours":27}]}]}', 'close-out,template,day-1 readiness', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-11 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 6, TO_TIMESTAMP('2026-10-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0016', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Activity Template', 'Day-1 readiness', 'Semiconductors & High-Tech', 'Diligence', '34-application inventory baseline', 'Build one reconciled list of in-scope applications with owners, hosting and users.', '{"activity":{"name":"34-application inventory baseline","description":"Build one reconciled list of in-scope applications with owners, hosting and users.","priority":"Medium"},"tasks":[{"title":"Collect CMDB and EA tool extracts","priority":"Low","day1_critical":"N"},{"title":"Run duplicate and gap quality check","priority":"Low","day1_critical":"N"},{"title":"Confirm business and IT owners","priority":"Medium","day1_critical":"N"},{"title":"Tag Day-1 critical applications","priority":"High","day1_critical":"N"},{"title":"Map applications to sites","priority":"High","day1_critical":"N"},{"title":"Sign off baseline with client CIO","priority":"Medium","day1_critical":"N"}]}', 'activity,template', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-11 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 5, TO_TIMESTAMP('2026-10-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0017', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Lesson', 'Day-1 readiness', 'Semiconductors & High-Tech', 'Day-1 Readiness', 'Start circuit orders in Signing, not Day-1', 'Network circuits took 120-170 days. Orders placed after signing put two sites at risk of missing Day-1. Place carrier orders as soon as site scope is known.', NULL, 'network,lead-time,day-1', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-11 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 7, TO_TIMESTAMP('2026-10-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0018', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Lesson', 'Day-1 readiness', 'Semiconductors & High-Tech', 'TSA Exit', 'Sequence low-dependency TSA services first', 'Exiting low-dependency services (email, service desk) two months early saved fees and freed the team for the hard ERP exit. Model exit order before the TSA is signed.', NULL, 'tsa,sequencing,cost', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-11 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 6, TO_TIMESTAMP('2026-10-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
