INSERT INTO knowledge_items (knowledge_id, source_project_id, source_label, item_type, deal_type, industry, stage_name, title, body, payload, tags, consent_status, review_status, reviewed_by, reviewed_at, times_used, created_at, created_by, updated_at, updated_by, is_deleted) VALUES ('KNW-0020', 'PRJ-0010', 'Semiconductor Day-1 carve-out (anonymised)', 'Risk', 'Day-1 readiness', 'Semiconductors & High-Tech', 'Signing', 'Licence consents found late', 'Several vendor licences needed consent to assign. Found during Day-1 prep, they forced short-term TSA extensions. Check assignment clauses during diligence.', NULL, 'licences,consent,risk', 'Granted', 'Approved', 'USR-0014', TO_TIMESTAMP('2026-10-11 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 8, TO_TIMESTAMP('2026-10-01 00:00:00.000', 'YYYY-MM-DD HH24:MI:SS.FF3'), 'USR-0014', NULL, NULL, 'N');
